package com.sharehope.submission.controller;
import com.sharehope.submission.dto.PublicSubmissionResponse; import com.sharehope.submission.repository.PublicSubmissionRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/submissions") @RequiredArgsConstructor
public class AdminSubmissionController{private final PublicSubmissionRepository repository;@GetMapping public List<PublicSubmissionResponse> list(){return repository.findAllByOrderByCreatedAtDesc().stream().map(PublicSubmissionResponse::from).toList();}
@PatchMapping("/{id}/status") public PublicSubmissionResponse status(@PathVariable java.util.UUID id,@RequestBody java.util.Map<String,String> body,@org.springframework.security.core.annotation.AuthenticationPrincipal org.springframework.security.oauth2.jwt.Jwt jwt){String status=body.getOrDefault("status","");if(!java.util.Set.of("NEW","CONTACTED","ACCEPTED","CLOSED").contains(status))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Invalid status");var value=repository.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));value.setStatus(status);value.setStatusUpdatedAt(java.time.OffsetDateTime.now());value.setStatusUpdatedBy(java.util.UUID.fromString(jwt.getSubject()));return PublicSubmissionResponse.from(repository.save(value));}
@PatchMapping("/{id}") public PublicSubmissionResponse workflow(@PathVariable java.util.UUID id,@RequestBody java.util.Map<String,String> body){var value=repository.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));String coordinator=body.get("assignedCoordinator"),notes=body.get("internalNotes");if(coordinator!=null&&coordinator.length()>200)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Coordinator is too long");if(notes!=null&&notes.length()>5000)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Notes are too long");value.setAssignedCoordinator(coordinator==null||coordinator.isBlank()?null:coordinator.trim());value.setInternalNotes(notes==null||notes.isBlank()?null:notes.trim());return PublicSubmissionResponse.from(repository.save(value));}
@DeleteMapping("/{id}") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void delete(@PathVariable java.util.UUID id){if(!repository.existsById(id))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND);repository.deleteById(id);}}
